class Solution {
public:
    vector<int> maxHammingDistances(vector<int>& nums, int m) {
        int total = 1 << m;
        vector<int> dist(total, -1);
        queue<int> q;

        for (int x : nums) {
            if (dist[x] == -1) {
                dist[x] = 0;
                q.push(x);
            }
        }

        while (!q.empty()) {
            int u = q.front();
            q.pop();
            int d = dist[u];
            for (int b = 0; b < m; ++b) {
                int v = u ^ (1 << b);
                if (dist[v] == -1) {
                    dist[v] = d + 1;
                    q.push(v);
                }
            }
        }

        int mask = total - 1;
        vector<int> ans;
        for (int x : nums) {
            ans.push_back(m - dist[x ^ mask]);
        }
        return ans;
    }
};

class Solution {
    public int[] maxHammingDistances(int[] nums, int m) {
        int total = 1 << m;
        int[] dist = new int[total];
        Arrays.fill(dist, -1);
        Queue<Integer> q = new ArrayDeque<>();

        for (int x : nums) {
            if (dist[x] == -1) {
                dist[x] = 0;
                q.offer(x);
            }
        }

        while (!q.isEmpty()) {
            int u = q.poll();
            int d = dist[u];
            for (int b = 0; b < m; b++) {
                int v = u ^ (1 << b);
                if (dist[v] == -1) {
                    dist[v] = d + 1;
                    q.offer(v);
                }
            }
        }

        int mask = total - 1;
        int[] ans = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            ans[i] = m - dist[nums[i] ^ mask];
        }
        return ans;
    }
}

var maxHammingDistances = function(nums, m) {
    const total = 1 << m;
    const dist = new Int32Array(total).fill(-1);
    const q = new Int32Array(total);
    let head = 0, tail = 0;

    for (let i = 0; i < nums.length; i++) {
        const x = nums[i];
        if (dist[x] === -1) {
            dist[x] = 0;
            q[tail++] = x;
        }
    }

    while (head < tail) {
        const u = q[head++];
        const d = dist[u];
        for (let b = 0; b < m; b++) {
            const v = u ^ (1 << b);
            if (dist[v] === -1) {
                dist[v] = d + 1;
                q[tail++] = v;
            }
        }
    }

    const mask = total - 1;
    const ans = new Array(nums.length);
    for (let i = 0; i < nums.length; i++) {
        ans[i] = m - dist[nums[i] ^ mask];
    }
    return ans;
};
